+func confirmPluginAction(ctx context.Context, prompt string, assumeYes bool) (bool, error) {
+	if assumeYes {
+		return true, nil
+	}
+	if !interactive.CanPromptInteractively() {
+		return false, fmt.Errorf("%w (%s)", errConfirmNeedsTerminal, prompt)
+	}
